<div class="row g-3"><div class="col-lg-5"><div class="card ems-card sticky-lg-top" style="top:84px"><div class="card-header">New approval chain</div><div class="card-body"><form method="POST" action="/admin/approval-chains" data-chain-form><?= csrf_field() ?><input type="hidden" name="company_id" value="<?= (int)$companyId ?>"><div class="row g-2"><div class="col-7"><label class="form-label">Name</label><input name="name" class="form-control" required placeholder="Standard leave approval"></div><div class="col-5"><label class="form-label">Module</label><select name="module" class="form-select"><?php foreach(['leave','attendance','overtime','loan','payroll'] as $m): ?><option value="<?= $m ?>"><?= ucfirst($m) ?></option><?php endforeach; ?></select></div><div class="col-8"><label class="form-label">Escalate after</label><div class="input-group"><input type="number" name="escalation_hours" value="24" min="1" class="form-control"><span class="input-group-text">hours</span></div></div><div class="col-4 d-flex align-items-end"><label class="form-check mb-2"><input class="form-check-input" type="checkbox" name="is_active" value="1" checked><span class="form-check-label">Active</span></label></div></div><hr><div class="d-flex justify-content-between"><strong class="small">Steps</strong><button type="button" class="btn btn-sm btn-soft" data-add-step><i data-lucide="plus"></i></button></div><div data-chain-steps><div class="chain-step border rounded p-2 mt-2"><input name="step_label[]" class="form-control form-control-sm mb-2" required placeholder="Manager review"><div class="row g-2"><div class="col-7"><select name="approver_type[]" class="form-select form-select-sm"><option value="manager">Employee manager</option><option value="role">Role</option><option value="user">Specific user</option></select></div><div class="col-5"><input name="reminder_hours[]" type="number" min="1" value="24" class="form-control form-control-sm" title="Reminder hours"></div></div><select name="role_slug[]" class="form-select form-select-sm mt-2"><option value="">Choose role if needed</option><?php foreach($roles as $r): ?><option value="<?= e($r['slug']) ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select><select name="user_id[]" class="form-select form-select-sm mt-2"><option value="">Choose user if needed</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['name']) ?></option><?php endforeach; ?></select></div></div><button class="btn btn-primary w-100 mt-3">Create chain</button></form></div></div></div><div class="col-lg-7"><?php if(!$chains): ?><div class="empty-state card ems-card py-5"><i data-lucide="git-branch"></i><strong>No approval chains yet</strong><div class="small text-secondary mt-1">Create one to enable escalation reminders.</div></div><?php endif; ?><?php foreach($chains as $chain): ?><div class="card ems-card mb-3"><div class="card-header d-flex justify-content-between"><div><span class="badge text-bg-light border text-capitalize"><?= e($chain['module']) ?></span> <strong><?= e($chain['name']) ?></strong></div><span class="badge <?= $chain['is_active']?'text-bg-success':'text-bg-secondary' ?>"><?= $chain['is_active']?'Active':'Paused' ?></span></div><div class="card-body"><div class="approval-timeline"><?php foreach($chain['steps'] as $step): ?><div class="d-flex gap-3 mb-3"><span class="avatar-sm"><?= (int)$step['step_order'] ?></span><div><strong><?= e($step['label']) ?></strong><div class="small text-secondary text-capitalize"><?= e($step['approver_type']) ?><?= $step['role_slug']?' · '.e($step['role_slug']):'' ?> · remind after <?= (int)$step['reminder_hours'] ?>h</div></div></div><?php endforeach; ?></div><div class="small text-secondary">Escalates after <?= (int)$chain['escalation_hours'] ?> hours.</div></div><div class="card-footer text-end"><form method="POST" action="/admin/approval-chains/<?= (int)$chain['id'] ?>/delete" data-confirm="Delete this approval chain?"><?= csrf_field() ?><input type="hidden" name="company_id" value="<?= (int)$companyId ?>"><button class="btn btn-outline-danger btn-sm">Delete</button></form></div></div><?php endforeach; ?></div></div>
<script>document.addEventListener('click',function(e){const b=e.target.closest('[data-add-step]');if(!b)return;const box=document.querySelector('[data-chain-steps]');const row=box.firstElementChild.cloneNode(true);row.querySelectorAll('input').forEach(i=>{if(i.name==='step_label[]')i.value='';});box.appendChild(row);});</script>
